[CmdletBinding()]
param([string]$Output='models/Qwen3.8-27B-UD-IQ3_S.gguf',[string]$Sha256,[string]$Url='https://huggingface.co/unsloth/Qwen3.8-27B-GGUF/resolve/main/Qwen3.8-27B-UD-IQ3_S.gguf')
$ErrorActionPreference='Stop';$p=Resolve-Path (Split-Path $Output -Parent) -ErrorAction SilentlyContinue;if(-not $p){New-Item -ItemType Directory -Force (Split-Path $Output -Parent)|Out-Null}
$free=(Get-PSDrive (Split-Path (Resolve-Path .).Path -Qualifier).TrimEnd(':')).Free;$expected=12040883104;if($free -lt ($expected+30GB)){throw "Insufficient free disk: $free bytes; require expected $expected + 30 GB headroom"}
$run='E0-IQ3S-'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmssZ');$cmd="powershell.exe -NoProfile -ExecutionPolicy Bypass -File scripts/s17_fetch_iq3s.ps1 -Output $Output -Sha256 $Sha256 -Url $Url";Write-Output "run=$run hypothesis=download only IQ3_S after >=30GB free; target=$expected bytes and SHA match command=$cmd";curl.exe -L --fail --retry 2 -o $Output $Url;if($LASTEXITCODE -ne 0){throw "download exit $LASTEXITCODE"};$h=(Get-FileHash $Output -Algorithm SHA256).Hash.ToLowerInvariant();if($Sha256 -and $h -ne $Sha256.ToLowerInvariant()){throw "SHA mismatch expected=$Sha256 actual=$h"};[ordered]@{schema='e0-iq3s-acquisition-v1';run_id=$run;timestamp_utc=[DateTime]::UtcNow.ToString('o');command=$cmd;path=$Output;bytes=(Get-Item $Output).Length;sha256=$h;expected_bytes=$expected;free_bytes_before=$free;status='downloaded'}|ConvertTo-Json|Set-Content ($Output+'.manifest.json');Write-Output "downloaded bytes=$((Get-Item $Output).Length) sha256=$h"